-- ---------------------------------------------------------------------------
-- 店铺知识库正文：一家店铺一段长文，这是进 Milvus 的唯一素材
--
-- 内容在离线阶段写好：
--   * 有关联用户博客的店铺（shop 1、shop 4）参考博客写成；
--   * 其余店铺按名称、类型、商圈、人均、评分、营业时间等信息合理推测着写。
-- 入库过程只做分块 + 向量化 + 写 Milvus，不再调用大模型，见 ShopKnowledgeServiceImpl。
--
-- 执行顺序：hmdp.sql -> agent_knowledge.sql -> shop_profile.sql -> 本文件。
-- 本文件可重复执行：每次先清空再写入，并把 content_hash 置空以触发重新入库。
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tb_shop_knowledge` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `shop_id` bigint(20) UNSIGNED NOT NULL COMMENT '店铺id',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '知识库正文，一整段连贯文字',
  `content_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上一次成功入库时的正文指纹',
  `chunk_count` int(8) NULL DEFAULT NULL COMMENT '入库分块数',
  `indexed_at` timestamp NULL DEFAULT NULL COMMENT '最近一次成功入库时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_shop_id`(`shop_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '店铺知识库正文' ROW_FORMAT = Compact;

DELETE FROM `tb_shop_knowledge`;

INSERT INTO `tb_shop_knowledge` (`shop_id`, `content`) VALUES
(1, '103茶餐厅开在大关商圈金华路锦昌文华苑29号，是一家沿街底商的港式茶餐厅，人均消费大约80元，综合评分3.7分，累计收到3035条评价、4215次消费，营业时间从上午十点到晚上十点，全周营业，中午吃个工作餐或者下午茶时段过来坐坐都合适。店面走的是怀旧TVB港风路线，绿色卡座、老式吊扇、墙上贴着旧港片海报，进门就有种九十年代香港街头的感觉，是这一带挺出片的一家小店。店内以四人卡座和双人小桌为主，桌距不算宽，饭点人多的时候会稍显拥挤，比较适合两三个人，人再多就不太好安排。\n\n菜品是这家店最拿得出手的地方。菜单很厚，从烧腊、碟头饭到菠萝油、丝袜奶茶一应俱全，几十种菜品均价在20元上下，在杭州的港式茶餐厅里算相当平价的，这也是它销量一直不错的原因。点得最多的是黯然销魂饭，38元一份，米饭上盖满甜口叉烧，配两颗溏心蛋，每一粒米都裹着酱汁，是店里点单率第一的主食。铜锣湾漏奶华28元，黄油吐司烤得脆脆的，表面撒可可粉，一刀切开奶盖像瀑布一样流出来，属于甜点类必点。神仙一口西多士16元，面包体柔软、黄油味浓，上面淋炼乳，分量不大，适合当饭后甜点。怀旧五柳炸蛋饭28元，四个鸡蛋炸成蓬松的炸蛋，再配大块鸡排和酸甜酱汁，很下饭，适合喜欢重口的人。想吃烧腊的可以点烧味双拼例牌，66元选烧鹅加叉烧，据说烧腊是每日从广州发货、到店现烧现卖，皮脆肉嫩，配梅子酱解腻，是店里单价最高的菜之一，但分量够两三个人分。红烧脆皮乳鸽18.8元一只，价格算便宜，肉质有嚼劲、脆皮酥香，一个人吃刚好。想一次多尝几样的可以点大满足小吃拼盘，25元含翅尖、咖喱鱼蛋、蝴蝶虾和盐酥鸡，其中咖喱鱼蛋评价最好。饮品推荐港式熊仔丝袜奶茶，19元，小熊造型的奶茶冰很上镜，茶味也够浓，配甜点刚好解腻。\n\n除了港式菜，这家店其实也做杭帮家常菜。东坡肉肥而不腻、入口即化，配米饭一绝；龙井虾仁用的是明前龙井，虾仁新鲜弹牙，茶香足；宋嫂鱼羹酸酸的比较开胃，适合饭前喝一碗；片儿川汤头清爽，面条偏硬有嚼劲。两个人点四个菜，人均六七十元也能吃得很饱，所以它更像是一家什么都能做的平价小馆，而不只是一家港式茶餐厅。\n\n需要提醒的是，这家店的综合评分只有3.7分，在同类里偏低，差评主要集中在服务响应慢和高峰期出餐慢这两点上，菜品的评价其实还不错。建议避开工作日午市12:00到13:30以及周末晚市高峰，去之前可以先看一下等位情况，或者干脆选下午两三点这种空档时段，上菜会快很多。沿街底商停车位很少，基本只能路边临时停靠，不建议开车过来，坐地铁或者步行是最省事的。点单时如果想吃多种烧腊，可以要求做成双拼，比单点划算不少；人多的时候先点主食再补小吃，避免一次点太多吃不完。\n\n如果是两个人来，比较实惠的搭配是一份主食加两份小吃、一杯饮品，例如黯然销魂饭配大满足小吃拼盘和港式熊仔丝袜奶茶，总共一百出头，吃得饱也不容易浪费；三个人可以再加一份烧味双拼，人均能降到七十以下，这也是这家店人多反而更划算的原因。店里经常有平台团购套餐和代金券，进店前先在手机上搜一下，通常比现场点单便宜十元左右，而且这类券一般当天可用、过期可退，属于比较稳妥的省钱方式。因为开在居民区底商，中午和傍晚的下班时段会有明显的两波客流，下午两点到四点是全天最空的时段，想安静坐一会儿的话可以挑这个时间。另外这家店没有包间，人多需要拼桌，十几人的聚会或者团建不太适合，最好控制在六人以内。整体来说，这是一家胜在性价比和怀旧氛围的小店，人均八十块能吃到港式茶餐厅和杭帮菜两个方向的菜，出品稳定但服务一般。适合一个人解决工作餐、下午茶，或者两三个朋友边吃边拍。如果你是冲着精致服务和安静环境去的，可能会失望；如果只是想花不多的钱吃点花样，它是这个商圈里比较实在的选择。'),
(2, '蔡馬洪涛烤肉·老北京铜锅涮羊肉位于拱宸桥与上塘一带的上塘路1035号，在中国工商银行旁边，是一家把炭火烤肉和老北京铜锅涮羊肉放在一起做的店，人均消费大约85元，综合评分4.6分，累计1460条评价、2160次消费，营业时间从上午十一点半一直持续到次日凌晨三点，是这一片少有的深夜食堂。\n\n店里最大的特点是没有休息时段，夜宵时间照样能吃到烤肉和涮肉，这在拱宸桥一带并不多见。烤盘用的是真正的炭火，不是电烤，炭火升温快、火力足，烤出来的肉带一点焦香，油烟处理做得不错，吃完身上味道不算重。铜锅是传统紫铜炭锅，锅底走的是老北京清汤路线，只放葱姜和枸杞，讲究的是羊肉本味，不靠重口味锅底抢戏。这种清汤锅底对羊肉品质要求高，反过来说，如果肉不新鲜很容易吃出来。\n\n羊肉以手切为主，羊上脑和羊后腿是点得最多的两个部位。羊上脑肥瘦相间、油脂分布均匀，涮八到十秒就能吃，入口嫩滑；羊后腿瘦肉多、有嚼劲，适合喜欢扎实口感的人。手切肉片厚薄均匀，这也是判断一家涮肉店水准的地方。蘸料是秘制麻酱，调得比较厚实，可以按自己口味加韭花酱、腐乳和香菜，麻酱配糖蒜是标准吃法，解腻又提味。除了涮肉，炭火烤盘这边可以烤羊肉串、烤羊排和各种蔬菜，很多客人是两样一起点，边烤边涮，一顿饭吃出两种体验。\n\n从消费结构上看，人均85元在杭州的烤肉店里属于中等水平，不算便宜也不算贵。人多的时候点套餐比单点划算不少，尤其是三到四个人，一份套餐再加一两个单点菜基本就够了，不用再额外加主食。需要注意的是，晚上十点以后是夜宵高峰，经常要等位，建议提前打个电话订位，或者稍微错峰到九点半之前到店。铜锅是清汤锅底，口味偏重的话可以另外点辣锅，或者多调一点麻酱和辣油。炭火烤盘升温很快，自己烤的时候注意翻面，羊肉串这种薄的东西很容易烤糊。\n\n位置在上塘路沿线，公交线路比较多，开车的话路边停车位不算充裕，晚高峰时段要绕几圈才能找到位置。\n\n点单上有个比较实用的思路：两个人来先点一份涮肉套餐，再按口味加一份烤串，这样涮和烤都能吃到，人均基本能控制在八十五左右；四个人以上就直接上套餐加两份烤肉，比全单点省不少。店里对涮肉的火候有讲究，服务员一般会提醒涮几秒，第一次来可以问一下，别一股脑全倒进锅里，肉老了口感差别很大。冬天的周末晚上是全年最挤的时候，尤其是冬至前后和降温那几天，不订位基本要等四十分钟以上，建议提前一天打电话。夏天生意会淡一些，座位好找，而且空调开得足，吃烤肉不会太受罪。因为营业到凌晨三点，凌晨一点之后厨房会陆续收档，想吃得赶在十二点半之前点完单。这家店适合的场景比较明确：朋友聚会、夜宵续摊、冬天想吃点热乎的。因为营业到凌晨三点，也很适合加班晚归或者看完夜场电影之后过来。如果是带长辈吃饭或者商务宴请，这里的氛围偏随意热闹，不太适合正式场合。综合来看，4.6分的评价对得起它的出品，属于性价比和氛围都还不错的深夜烤肉店。'),
(3, '新白鹿餐厅运河上街店开在台州路2号运河上街购物中心五楼，是杭州本地连锁杭帮菜品牌里性价比的代表之一，人均消费大约61元，综合评分4.7分，累计收到8045条评价、12035次消费，营业时间从上午十点半到晚上九点，是标准的商场餐饮作息。\n\n餐厅装修走的是偏现代的中式风格，大厅桌距比较宽，圆桌和四人桌都有，也有适合六到八人的大桌，翻台速度快，是典型的商场店节奏。因为桌距宽、环境干净，带老人和小孩来都比较方便，家庭聚餐的场景占了不少比例。\n\n菜品是标准的杭帮口味，整体偏甜偏清淡，分量给得实在。点得最多的是蛋黄鸡翅，外壳酥脆、蛋黄味浓，是几乎每桌都会点的一道；糖醋排骨酸甜比例比较平衡，肉质软烂，骨头容易脱；白鹿豆腐是店里的招牌素菜，外皮煎香、里面嫩滑，汤汁很下饭；龙井虾仁用的是明前龙井，虾仁弹牙、茶香清爽，属于杭帮菜里的经典；砂锅鱼头分量足、汤头浓，适合人多的时候点；西湖醋鱼是经典杭帮做法，酸甜带一点蟹味，不过这道菜口味比较有辨识度，第一次吃的话建议先问一下做法再决定。想吃点蔬菜的可以点清炒时蔬或者油焖笋，解腻效果不错。\n\n价格是这家店最大的优势。人均61元在这个评分段里算很实惠，三四个人点五六个菜通常也不会超预算，人越多越划算。因为开在购物中心里，逛完街直接上楼吃饭很方便，吃完饭还能继续在商场里逛，是周末一站式安排比较省事的选择。\n\n需要注意的是排队。这家店口碑稳、评价数超过八千条，饭点排队经常要30到60分钟，尤其是周末和节假日的晚餐时段，有时候前面会排几十桌。建议尽量在11:00前或者13:30之后到店，也可以先在门口取号，再去商场里逛一圈等叫号，比站在门口干等舒服。商场有地下停车场，但周末车位比较紧张，来晚了要排队进场，建议提前一点到。另外杭帮菜整体偏甜，不习惯甜口的可以在点菜时跟服务员说少放糖，或者多搭配一些咸鲜和清炒的菜平衡一下。\n\n点菜时有个省心的办法：第一次来就照着菜单上的招牌菜点，蛋黄鸡翅、糖醋排骨、白鹿豆腐、龙井虾仁这四道基本不会出错，再配一份时蔬和一份汤，三到四个人就够吃了。人多的话加砂锅鱼头和西湖醋鱼，这两道分量大、适合分食。店里的菜品分量偏大，两个人点三道菜通常就够，点多了容易剩，可以吃完再补。中午的商务套餐和下午茶时段价格更优惠，工作日午市人相对少一些，如果时间灵活可以考虑中午来。和运河上街同楼层的其他餐厅比，新白鹿的翻台最快、等位最久，翻台快意味着菜品周转快、比较新鲜，但代价就是坐不久，聊天的局不太适合，吃完基本就该让位了。如果想要坐得久一点，同层的羊老三或者楼下的港式餐厅更合适。总体而言，新白鹿是那种不会出错的杭帮菜选择：出品稳定、价格实惠、位置方便、服务流程标准化，评分4.7分也说明它的口碑经得起检验。想吃正宗杭帮菜又不想花太多钱，这里是运河上街一带比较稳妥的一家。它不适合追求精致摆盘和私密空间的场合，但作为日常聚餐和家庭吃饭，性价比很难挑出毛病。'),
(4, 'Mamala杭州远洋乐堤港店位于丽水路66号远洋乐堤港商城二期一层B115号，是这一批店铺里评分最高的一家，综合评分4.9分，累计9529条评价、13519次消费，人均消费大约290元，营业时间从上午十一点到晚上十点。\n\n这家店最出名的是它的环境。进门就是满眼的鲜花和绿植，餐桌上、吧台上、角落里到处是花艺布置，花不是随便摆几束，而是整个空间统一设计过的，晚上灯光调暗以后氛围感很强，是杭州挺有名的约会和纪念日餐厅。餐厅的座位以两人桌和四人桌为主，也有相对独立的区域，适合需要一点私密感的场合。服务员会主动帮忙拍照，很多人是专门冲着出片来的，店里也见惯了这种需求。值得一提的细节是，服务员在介绍菜品时比较耐心，会认真推荐特色菜并配合拍照需求。\n\n菜品方面，餐厅整体走西餐路线，出品稳定，摆盘讲究。战斧牛排是招牌，分量很大，建议点五分熟，外层焦香、切开有汁水，全熟会偏柴，两个人分着吃比较合适。奶油培根意面奶香浓郁，面条裹满酱汁，属于很扎实的一道主食，一个人吃可能就半饱了。香菜汁烤鲈鱼是带辣的一道菜，鲈鱼本身嫩、没什么刺，烤过之后外皮微酥，配上带香菜的辣酱很开胃，不吃辣的要提前说，这道菜的评价也比较两极。酒水可以试试维亚红酒马瑟兰，微醺上头，配牛排比较合适，工作日的疲惫感会被冲淡不少。\n\n需要提前想清楚的是价格。人均290元在杭州西餐厅里属于偏高的水平，其中相当一部分是环境溢价。如果是日常朋友聚餐，同样的钱在别处能吃得更好；但如果是为了约会、表白、纪念日或者生日这类需要氛围和仪式感的场合，这个价格是可以接受的，毕竟环境本身就是消费内容的一部分。强烈建议提前预订，尤其是靠花丛和靠窗的位置，这两个位置的出片效果最好，当天到店很可能没有好位子。远洋乐堤港本身有地下停车场，商场营业时段停车比较方便，吃完还可以在商场里逛逛。\n\n点餐搭配上，两个人比较合理的组合是一份牛排加一份意面再加一份前菜或沙拉，战斧牛排本身分量就大，两个人分刚好，再各点一杯酒水，总价大致在六百上下。如果预算有限，可以只点意面和烤鲈鱼，人均能压到两百以内，同样能享受到环境。想拍照的话，建议选晚上七点以后的时段，那时灯光调暗、氛围最好；白天光线足，出片风格会偏清新一些，看个人喜好。过纪念日可以提前跟店里说，一般能安排桌面布置和餐后小惊喜，这类需求最好预订时一并提出来，当天临时说往往来不及。另外用餐高峰是晚上六点半到八点半，这个时段上菜会慢一些，赶时间或者带了小朋友的话，建议约在五点半或者八点半之后。周末中午相对安静，适合想安安静静吃顿饭又不想花太多时间等位的人。综合来看，Mamala是一家定位清晰的餐厅：它卖的不只是菜，更是环境和仪式感。把它当成一家纪念日餐厅来安排，体验会很好；把它当成日常吃饭的地方，会觉得贵而且性价比一般。4.9分的评分和超过九千条评价说明它在自己擅长的场景里做得确实不错，选对场合去，基本不会踩雷。'),
(5, '海底捞火锅水晶城购物中心店开在上塘路458号水晶城购物中心六楼，是海底捞的服务标杆店之一，人均消费大约104元，综合评分4.9分，累计2764条评价、4125次消费，营业时间从上午十点一直到次日早上七点，是这个片区最晚收档的火锅店之一，半夜想吃火锅也完全来得及。\n\n锅底可以选四宫格自由搭配，一次能吃到四种口味，人少的话也可以选双拼，灵活性比较高。点得最多的组合是番茄锅加牛油麻辣锅，番茄锅酸甜浓郁，适合涮蔬菜和给孩子吃；牛油麻辣锅香气足、辣度可以调，喜欢重口的可以让服务员加辣。菜品里捞派滑牛肉、虾滑、毛肚、鸭肠是常规必点，滑牛肉口感嫩滑，虾滑可以自己下也可以让服务员帮忙，毛肚讲究七上八下涮几秒。捞面有现场表演，师傅会边拉面边舞动，比较适合带朋友或者小孩来看，气氛很好。\n\n等位区是这家店的一大特色，提供免费小吃、饮品和水果，还有免费美甲和儿童乐园，等一两个小时也不算太难熬，这也正是海底捞区别于普通火锅店的地方。带孩子来的家长可以把孩子放在儿童乐园，自己在旁边休息，这一点对家庭客群很友好。\n\n价格方面，人均104元是包含锅底和小料之后的大致水平，属于中等偏上。两个人点菜要注意别点多，海底捞的分量不算小，半份菜是个不错的选择，可以多点几样又不容易剩。小料台是自助的，按人头收费，调的时候可以试试经典的蒜泥香油碟和麻酱碟各来一份。大学生在特定时段有专属折扣，可以主动问一下服务员，不问的话一般不会主动提。\n\n最需要注意的是排队。晚上18:00到21:00是绝对高峰，等位经常超过一小时，务必先用小程序远程取号再出门，不要直接到店干等，这是最影响体验的一点。水晶城购物中心里有停车场，但要注意晚上十点之后商场入口会调整，跟着标识走。另外这家店营业到早上七点，深夜时段人少、上菜快、服务节奏也更从容，如果不想等位，宵夜时段来体验会好很多。\n\n点单上比较实用的经验是：两个人点一个四宫格锅底加四五样半份菜正好，三到四个人点六到八样半份菜，比点整份更灵活也更省。小料台的收费是按人头算的，进场就会计上，不用的话可以提前跟前台说。捞面表演一般集中在晚市高峰时段，想看的话可以挑七点到八点之间，其他时段师傅可能不表演。带孩子来的家庭建议选靠窗或者角落的位置，离儿童乐园近一些，方便照看。等位时可以先在手机上把小料和菜品想好，进座后直接下单，能省不少时间。深夜时段（凌晨十二点之后）人很少，上菜快、服务员也相对从容，如果只是想安安静静吃顿火锅，这个时段体验反而比饭点好。另外这家店和商场其他店铺共用停车资源，周末车位紧张，建议提前留出找车位的时间。综合来看，海底捞的优势在于服务、营业时长和出品稳定性，4.9分的评分很能说明问题。它的价格不算便宜，也不见得是最好吃的火锅，但如果看重服务体验、需要带孩子和老人一起吃饭、或者想在深夜找个地方慢慢吃，这里是水晶城一带比较省心的选择。'),
(6, '幸福里老北京涮锅丝联店开在金华南路189号丝联166号，在丝联166文创园里面，人均消费大约130元，综合评分4.6分，累计7324条评价、9531次消费。营业时间比较特殊，中午11:00到13:50，晚上17:00到20:50，中间是休息的，比一般餐厅收档早不少，去之前一定要看好时间。\n\n文创园本身是旧厂房改造的，红砖墙面配绿植，环境安静，不像商场店那么吵，园区里还有一些文创小店和咖啡馆，可以提前到或者饭后在园子里走走。店里也延续了这种调性，木质桌椅、怀旧陈设，桌距比较宽，适合慢慢吃、慢慢聊，而不是吃完就走的那种节奏。\n\n这家店主打传统老北京铜锅涮肉，用的是紫铜炭锅，锅底很简单，就是清水加葱姜枸杞，讲究的是羊肉本身的味道。这种锅底对肉的品质要求很高，肉不新鲜一涮就能吃出来，所以敢用清汤的店通常对食材有底气。手切鲜羊肉是招牌，肉片切得均匀、厚薄一致，涮几下就熟，口感嫩而有弹性。麻酱小料调得厚实，可以自己加腐乳、韭花和香菜，配糖蒜一起吃很地道，甜辣酸香一起上，解腻效果很好。除了涮肉，爆肚、羊上脑、羊尾油也值得点，爆肚脆嫩，蘸麻酱是标准吃法，火候要自己掌握，涮久了会老。\n\n价格上人均130元属于偏高的水平，建议直接点套餐，比单点划算，两个人点一个套餐基本够吃，如果胃口不大甚至还会剩。如果想多尝几样，可以套餐之外再加一两个单点菜，比如爆肚或者烤串。\n\n需要特别提醒的是营业时间：中午13:50、晚上20:50就收档了，去晚了真的会吃不上，这一点和大部分餐厅不一样，很多人第一次去都会踩这个坑。建议中午11点半到12点、晚上5点半到6点这个区间到店，时间比较从容。另外文创园里停车位比较充足，开车过来比去商场店方便得多，这也是它比同价位商场店更舒服的地方。铜锅是清汤锅底，如果口味偏重，可以另外要辣碟，或者多调麻酱。\n\n两个人来点一个涮肉套餐基本就够，套餐里一般包含手切羊肉、配菜和主食，不够的话加一份爆肚或者糖蒜就行。四五个人建议点套餐再单加两盘肉，这样比全单点省三成左右。因为锅底是清汤，涮的顺序也有讲究：先涮羊肉喝一轮汤，再下蔬菜和豆腐，最后下面条或者烧饼，汤会越煮越鲜，反过来先下菜的话汤容易发苦。糖蒜建议一人一份，配麻酱解腻效果很明显。冬天是这家店的旺季，尤其是十一月到次年二月，周末基本满座，建议提前一天订位；夏天生意淡一些，位置好找。另外因为收档早，晚上八点之后就不再接待新客了，想吃得赶早。文创园里除了这家店还有咖啡馆和其他餐饮，饭前饭后可以顺路逛一逛，整体体验比商场店更从容。总体来看，这是一家环境和出品都在线的老北京涮肉馆，适合想吃点传统涮肉、又不喜欢商场店嘈杂氛围的人。人不多的时候，坐在老厂房改造的空间里慢慢涮一锅羊肉，配上糖蒜和麻酱，体验是挺好的。缺点是时间窗口窄、价格偏高，安排之前先把时间确认好。'),
(7, '炉鱼拱墅万达广场店开在杭行路666号万达商业中心4幢2单元409室，铺位号4005，在商场四楼，人均消费大约85元，综合评分4.7分，累计1320条评价、2631次消费。这家店最大的特点是没有休息时间，全天24小时营业，深夜看完电影或者加班到很晚，都能在这里吃上一顿热乎的，这在商场餐饮里比较少见。\n\n店里主打烤鱼，口味选择很多，豆豉、香辣、蒜香、酸菜都有，也可以按辣度调整。鱼都是现烤的，从下单到上桌需要等一会儿，外皮烤得焦香，鱼肉保持嫩度，底下铺的配菜吸满了汤汁，很下饭，很多人是冲着配菜来的。豆豉味是最经典的一种，咸香不辣，适合大多数人的口味，也是第一次来比较稳妥的选择；香辣味更刺激，适合能吃辣的，可以配冰饮；蒜香味蒜香浓郁，配米饭特别合适；酸菜味偏酸爽，冬天吃很开胃。烤鱼的分量普遍偏大，一般是两个人分一条，再搭配一两个配菜。配菜可以自选，土豆片、藕片、宽粉、金针菇都是常见选择，其中宽粉和土豆片吸汤汁最厉害，建议至少点一样。\n\n除了烤鱼，店里一般也有一些凉菜和小吃，可以等烤鱼的时候先垫一垫。饮料方面以常规的碳酸饮料、酸梅汤为主，价格和商场其他餐饮差不多。\n\n价格方面，人均85元属于正常水平，烤鱼本身单价不高，主要的开销在配菜和饮料上，如果不控制很容易超预算。需要提醒的是，虽然全天营业，但凌晨时段部分菜品可能会售罄，选择会少一些，而且现烤需要时间，深夜着急的话要做好等的准备。另外烤鱼分量真的很大，两个人点一条再加一两个配菜就够了，容易点多浪费，三个人以上点两条比较合适，人再多可以不同口味各来一条。\n\n位置在万达广场里面，看电影、逛街都很方便，商场停车位充足，看电影的话还能凭票减免停车费，这一点比较划算。辣度可以调整，怕辣的点豆豉或蒜香就行，带孩子来的话建议直接选不辣的。\n\n点菜时要注意辣度的传递顺序：菜单上标注的辣度是整锅的，一旦选了三档以上的辣，配菜和汤汁都会很辣，带孩子或者有不吃辣的人同桌，建议点鸳鸯或者选豆豉这种不辣的口味。上桌之后先吃鱼和配菜，等汤汁收得差不多了再下面条或者泡饭，这个时候汤汁最浓，是这顿饭最好吃的一口。两个人的标准配置是一条鱼加两个配菜，三个人的话点两条不同口味的鱼更划算，还能对比着吃。下午三四点和深夜十一点之后是两个相对空档的时段，不用等位、上菜也快，赶时间的话可以挑这两个时间。因为全天营业，店里会轮班，服务水准在不同时段略有差别，深夜时段人手少，加菜可能要自己招呼。另外商场在晚上十点后部分入口会关闭，从地下车库上来要跟着指示走，第一次来容易绕。综合来看，这是一家很实用的店：24小时营业解决了很多时候想吃热食但选择有限的问题，4.7分的评分说明出品稳定，烤鱼本身也是适合分享的品类。适合深夜觅食、逛商场顺便吃饭、朋友小聚这类场景。如果追求精致环境和安静氛围，商场店的通病是饭点比较吵，这一点要有心理准备。'),
(8, '浅草屋寿司运河上街店开在拱墅区金华路80号运河上街B1层，是地下商业层里的一家日料小店，人均消费大约88元，综合评分4.6分，累计1206条评价、2406次消费，营业时间从上午十一点到晚上九点半。\n\n店面不大，装修是简洁的日式木质风格，原木色调配暖光，吧台位可以看到师傅现场制作，适合一个人安静地吃一顿，或者逛街途中坐下来吃点轻食。座位以吧台和双人桌为主，桌数不多，高峰期会显得比较紧凑，人多的话建议提前一点到，或者干脆避开饭点。\n\n店里主打寿司和刺身，同时也做鳗鱼饭、天妇罗这类熟食，出品以新鲜度和稳定为主。点得比较多的是三文鱼刺身，切片厚实、油脂分布均匀，入口化开，是判断日料店水准的一道基础菜；鳗鱼饭酱汁甜咸适中，鳗鱼烤得软糯，配米饭很香，分量适中，一个人吃刚好；天妇罗炸得酥脆不油腻，虾和蔬菜都有，蘸天妇罗汁吃；寿司拼盘适合想一次尝多种的人，一般会配几种常见鱼生和玉子烧；味增汤可以搭配着点，暖胃。想吃得清淡一点可以点刺身拼盘配茶碗蒸，想吃得饱一点就选鳗鱼饭或者天妇罗盖饭。\n\n价格方面，人均88元在日料里属于中等偏下，午市套餐尤其划算，通常包含主食、小菜和汤，比晚市单点便宜不少，所以如果只是想简单吃个日料午饭，中午来性价比最高。晚市单点的话要注意刺身类价格上得快，点之前可以大致算一下。\n\n需要注意的几点：这家店以生食为主，肠胃比较敏感或者孕妇要谨慎选择，可以多点天妇罗、鳗鱼饭这类熟食，安全性更高。晚市18:00之后客流集中，可能要等位，建议错峰或者提前一点到。店在地下楼层，手机信号一般，可以先用商场WiFi。运河上街本身是购物中心，逛完街下楼吃饭很方便，停车可以停在商场地下车库，但周末车位也紧张。\n\n点单上，一个人来推荐鳗鱼饭配味增汤，或者直接点午市套餐，性价比最高；两个人可以点半份刺身加一份寿司拼盘，再搭一份天妇罗，荤素和生熟都照顾到。刺身类的菜建议先点再补，不要一次点太多，生食放久了口感下降明显。茶水一般是免费的，可以要一杯热茶暖胃。因为店面小、桌数少，中午十二点到一点是排队最集中的时段，写字楼上班族多，建议十一点半之前或者一点之后到。晚市相对宽松，但六点半之后也会坐满。店里没有包间，人多的话要拼桌或者提前打电话问能不能留位。商场B1层餐饮集中，节假日整体人流大，电梯口附近会比较拥挤，推婴儿车的话建议走扶梯旁边的通道。总体来看，浅草屋是一家定位清晰、价格实在的日料简餐店，适合工作日午饭、一个人吃饭、或者逛街途中想吃得清爽一点的场景。它的优势是新鲜度和午市性价比，不适合需要包间、需要长时间坐着聊天的聚会场合。'),
(9, '羊老三羊蝎子牛仔排北派炭火锅运河上街店开在台州路2号运河上街购物中心五楼，和新白鹿在同一层，人均消费大约101元，综合评分4.4分，累计1363条评价、2763次消费，营业时间从上午十一点到晚上九点半。\n\n这家店专做北派火锅，主打羊蝎子和牛仔排，用的是炭火铜锅慢炖。端上来就是咕嘟咕嘟冒着热气的一大锅，视觉上很有冲击力，冬天进门看到这一锅会觉得特别暖和。羊蝎子炖得酥烂脱骨，肉一拨就下来，骨髓可以用吸管吸，这是很多人专门来这里的理由；牛仔排肉厚实、有嚼劲，适合喜欢大口吃肉的人，两种锅底也可以做成双拼，人多的时候建议直接双拼，两种都尝到。除了两个主锅，手切羊肉、羊杂也可以另外加，涮在锅里一起吃。蘸料走北方路线，麻酱加韭菜花、腐乳，味道比较厚重，配着炖得酥烂的羊肉层次感更足。\n\n店里整体是北方馆子的风格，量大实在，桌面大、锅大，适合三五个朋友围一桌慢慢吃。服务节奏偏慢，属于那种不催你、你自己慢慢涮的店。\n\n价格上人均101元属于中等偏上，但因为分量大，人越多越划算。建议三个人以上点一个锅，两个人吃容易剩，特别是还点了配菜的情况下。点锅的时候可以让服务员推荐分量，避免点多。\n\n需要提醒几点：综合评分4.4分，略低于同楼层的其他餐厅，主要的负面反馈是口味偏咸和上菜偏慢。羊蝎子本身口味就偏重偏咸，这是这道菜的特点，清淡口味的可以在点单时要求少盐，或者多涮点蔬菜中和一下，娃娃菜和白萝卜比较吸味，很合适。炭锅加热比较慢，从点单到开吃需要等一会儿，赶时间的话要预留出这个时间，或者提前打电话问能不能先炖上。位置在运河上街五楼，商场地下有停车场，交通和停车都比较方便，吃完还能在同层或者楼下继续逛。\n\n吃羊蝎子有个顺序上的讲究：先吃锅里的蝎子和牛仔排，啃完一轮之后再让服务员加汤涮菜，这样肉的火候正好，菜也不会被炖烂。吸骨髓建议趁热，凉了会凝固。配菜里娃娃菜、白萝卜、宽粉最吸味，但也会把汤吸咸，建议最后再下。饮料方面，因为口味偏重，配酸梅汤或者冰镇饮料比配茶更解腻。四个人以上点双拼锅最合适，两个人点单锅再加一两样配菜就够，别一上来就按人数点菜，锅里的量比看上去多。冬天周末是全年的高峰，需要提前订位；平日晚上相对宽松，中午人最少，想安静吃的话中午来。因为炭锅上桌后还要炖一会儿，从落座到能下筷大概要等十几分钟，带小孩的话可以提前要点小吃垫一垫。总体而言，这家店适合冬天聚餐、朋友围炉吃肉这类场景，主打的是实在和氛围，而不是精致。锅一端上来、热气腾腾地开始涮，那种围坐的感觉是它的价值所在。如果是一个人吃饭或者追求清淡口味，这家店就不太合适了。'),
(10, '开乐迪KTV运河上街店开在台州路2号运河上街购物中心四楼，是一家量贩式KTV，人均消费大约67元，综合评分3.7分，累计902条评价、26891次消费，是这一片销量最大的KTV之一。它最大的特点是全天24小时营业，凌晨时段价格还会再降一档，非常适合预算有限、想随便唱唱或者深夜续摊的场合，销量数据也说明它靠低价吸引了很多客流。\n\n从硬件来看，店里包厢数量比较多，平时不需要怎么等位就能开唱，高峰期以外基本随到随唱，这一点比一些热门KTV强。包厢大小从三四人的小包到十几人的大包都有，朋友聚会或者部门小聚都能安排。曲库更新速度尚可，热门新歌基本都能点到，老歌也比较全，怀旧向的歌单做得还可以。点歌系统是常规的触屏点歌，操作不算新但能用。\n\n价格是这家店的核心竞争力。人均67元是附近KTV里最便宜的之一，配合24小时营业，凌晨场和下午场的性价比尤其高，学生党和预算有限的年轻人是主要客群。不过要注意酒水和小吃的定价偏高，这是量贩式KTV常见的盈利方式，进店前最好先问清楚价格，或者直接选带酒水小吃的套餐，通常比现场单点便宜。部分时段还可以自带酒水，具体规定建议提前电话确认。\n\n需要客观提醒的是，这家店的综合评分只有3.7分，是附近KTV里偏低的一家。差评主要集中在设备老旧、麦克风有杂音、部分包厢音响效果一般，以及隔音不够好这几个方面。如果对音质和包厢环境要求比较高，建议考虑同商圈的其他几家，比如水晶城的INLOVE或者万达的星聚会；如果只是想找个地方热闹一下、唱唱歌聊聊天、对音质没那么在意，这个价格是划算的。另外因为客流大，卫生状况的表现不太稳定，介意的话进去之后可以先检查一下包厢。\n\n位置在运河上街购物中心四楼，可以下午先在楼下吃饭逛街再上楼唱歌，商场地下有停车场，交通方便。\n\n消费上有几个能省钱的点：一是尽量选套餐，尤其是带酒水小吃的欢唱套餐，通常比裸唱加现场点单便宜三成左右；二是挑时段，工作日下午和凌晨时段的价格明显低于晚高峰，同样时长能省一半；三是自带酒水，部分时段允许，但一定要提前电话确认，不同门店和时段规定不一样。唱歌之外，店里一般还有骰子、桌游之类的道具可以借，聚会时能多一项活动。如果对音质有要求，建议订房时直接说明要新装修的包厢，前台通常能安排，不要等到进房以后才发现不满意再换，那时候可能没得换。散场时间比较晚的话，商场部分出入口会关闭，只能走指定通道，跟着指示牌走不会绕。综合来看，开乐迪属于典型的量大价低型KTV，胜在便宜和随时能唱，适合学生聚会、深夜续摊、预算有限的场合，不适合对设备和环境有较高要求的人。选它之前，先明确自己更看重价格还是体验。'),
(11, 'INLOVE KTV水晶城店开在上塘路458号水晶城购物中心6层，是一家连锁KTV，也是这一批KTV里综合评价最高的一家：人均消费大约75元，综合评分4.7分，累计5684条评价、销量35977，数据在同类里相当突出。营业时间从上午十一点半一直持续到次日凌晨六点，下午场、晚场、通宵场都能安排。\n\n从硬件和环境来看，这家店的装修比较新，包厢空间大，不会出现小包厢挤得转不开身的情况，音响和灯光效果都在线，是它评分高的主要原因之一。曲库更新也比较快，热门新歌基本能和线上同步，不太会出现想唱的歌点不到的情况；老歌和方言歌曲也比较全，一桌人年龄跨度大的话不容易冷场。点歌系统操作顺畅，支持手机点歌。店里有主题包厢，可以提前指定，氛围布置比普通包厢更有意思，适合生日、朋友聚会和公司团建这类需要一点仪式感的场合。服务水平在连锁品牌里属于稳定发挥，评分和评价数说明它没有明显的短板。\n\n价格方面，人均75元属于中等水平。需要注意的是，这个价格通常是裸唱价，酒水小吃另算，而包厢内的酒水价格一般高于外面，所以点单时要留意，这也是很多人结账时觉得超预算的原因。比较划算的做法是提前买团购欢唱套餐，一般会包含酒水和小吃，折算下来比现场单点便宜不少，而且套餐通常按时段和时长区分，下午场更便宜。\n\n最需要提前规划的是订房。周五和周六晚上20:00到24:00是绝对高峰，建议提前一到两天订房，当天临时去很可能没有包厢，尤其是大包和主题包厢，节假日甚至要提前更久。水晶城购物中心有停车场，可以直达六层，开车过来比较方便，消费一般也能对应一定的免费停车时长。如果散场时间太晚（凌晨三四点），建议提前叫车，那个时段不太好打到车，也可以提前跟前台预约出租车。\n\n订房有一些细节能明显影响体验：一是明确人数和用途，说清楚是生日、聚会还是纯唱歌，前台会据此推荐包厢大小和能不能布置；二是问清楚套餐包含的时长和续时价格，避免唱到一半被动加钱，续时通常按半小时计费；三是确认酒水能不能自带，不少连锁门店允许带蛋糕但不允许带酒；四是留意团购券的使用时段限制，便宜的套餐往往限定工作日下午。进场后建议先把空调温度和音响音量调好，再开始点歌，尤其冬天包厢升温慢。通宵场注意保暖，包厢空调到后半夜会比较凉。另外唱歌时间长了嗓子容易干，店里的热水一般免费，可以主动要。同一批人如果经常来，可以留意会员卡或者储值活动，长期算下来比每次团购更划算。综合来看，INLOVE是这一片最稳妥的KTV选择：设备新、口碑稳、营业时间长、价格不算贵，缺点主要是高峰时段难订房和酒水偏贵。无论是朋友聚会、生日局还是通宵场，都比较适合，前提是记得提前订房、并且对酒水消费有预期。'),
(12, '魅杭州远洋乐堤港店开在丽水路58号远洋乐堤港F4，人均消费大约88元，综合评分4.6分。目前累计评价235条、销量6444，营业时间从上午十点到次日凌晨两点。\n\n这家KTV走的是偏华丽、偏夜店风的路线，和传统的量贩式KTV风格差别明显。走廊和包厢的灯光做得很讲究，会用灯带、投影和镜面做氛围，进门就很有感觉，是这一片比较出片的一家，适合喜欢拍照、想发朋友圈的年轻人聚会。包厢的沙发和茶几配置偏向小型派对，坐起来宽敞，适合边唱边聊。音响的低音表现不错，唱流行和电音比较带感，适合热闹的场合；如果唱民谣或者老歌，可能会觉得低音有点重，可以调一下音效模式。位置就在远洋乐堤港里面，可以下午先在楼下吃饭逛街，晚上再上楼唱歌，一条龙安排比较省事，商场地下有停车场。店里也承接生日会、聚会包场这类需求，可以提前沟通布置。\n\n价格方面，人均88元在KTV里属于偏高的水平，其中相当一部分是环境溢价，酒水小吃同样另算。如果只是想单纯唱歌、对装修和氛围没有特别要求，这个价格不如考虑同商圈更便宜的选择，比如运河上街的开乐迪；如果是为了办生日、聚会或者拍照，多花的钱换来的是氛围和出片效果，是可以接受的。建议提前问清楚有没有套餐和包场价格，包场通常比按人头算更划算。\n\n需要提醒的是，这家店的评价数目前只有235条，样本相对偏少，和动辄几千条评价的连锁店比，它的口碑数据还不够充分。建议在下单或者订房前先翻一下最新的评价，看看近期设备、卫生和服务的实际反馈，避免只看总分就下判断，尤其是要留意有没有关于音响故障或者服务响应的近期反馈。远洋乐堤港有地下停车场，商场营业时段停车比较方便，散场晚的话同样建议提前叫车。\n\n如果是为了聚会或者生日，建议提前跟店里沟通几个细节：能不能带蛋糕、能不能布置气球和灯牌、能不能自带酒水，这三件事不同门店规定不一样，提前问清楚能避免到现场尴尬。包场之前最好实地看一次包厢，照片和实际效果在小包厢上差别比较明显。拍照的话，走廊和部分包厢的灯光更适合出片，可以让服务员推荐机位。时段上，晚上十点之后的氛围最好但也最贵，想省钱又想有氛围，可以选九点前后进场，正好赶上灯光效果又避开最贵的时段。因为这家店评价样本少，建议优先看近半年的评论，重点留意设备故障率和服务响应速度，这两项是KTV体验里最容易踩坑的地方。远洋乐堤港周边餐饮选择多，可以晚饭后直接上楼，动线比较顺。综合来看，魅是一家定位偏精致、偏氛围的KTV，适合生日、聚会、拍照这类有仪式感需求的场景，不适合只想花最少的钱唱几小时的人。选它之前最好明确一下这次的核心诉求是氛围还是性价比。'),
(13, '讴K拉量贩KTV北城天地店开在湖州街567号北城天地5层，商圈属于D32天阳购物中心一带，人均消费只要58元，综合评分4.1分，累计1857条评价、18997次消费，营业时间从中午十二点到次日凌晨两点。\n\n这家店走的是薄利多销路线，人均58元是这几家KTV里最便宜的，也是它最大的卖点。包厢面积普遍较大，一次容纳十几个人不成问题，桌子也够大，适合摆饮料和零食，非常适合学生党、班级聚会、社团活动这类人数多、预算有限的场合。因为价格低，店里客流一直不小，销量接近1.9万也说明了这一点，高峰期包厢周转比较快。下午场价格是全天最低的，如果想省钱，下午过来最划算，工作日下午基本不用等位。\n\n设施方面，点歌系统和音响都是偏老的配置，能正常使用但谈不上好，曲库更新速度也一般，最新的热门歌曲不一定能第一时间点到。包厢内一般有沙发和茶几，空间上比同价位的店宽松，这是它的优势。\n\n需要客观提醒几点。第一，综合评分4.1分，设备和装修整体偏老，音响效果和包厢环境比不上新开的店，对音质有较高期待的话建议降低预期或者换一家，比如同商圈的INLOVE。第二，营业时间从中午12:00才开始，上午是不营业的，安排上午场的话来不了，这一点和24小时营业的店不一样。第三，酒水和小吃的定价偏高，这是低价KTV的常见做法，如果想自带零食和饮料，最好先打电话确认门店的相关规定，避免到了门口产生纠纷。第四，高峰时段虽然不及市中心那么夸张，但周末下午和晚上依然建议提前订房，尤其是大包。第五，客流大意味着卫生水平波动，介意的话进包厢后可以先检查一遍。\n\n位置在北城天地5层，商场和周边停车比较方便，公交线路也多，交通不是问题。\n\n学生团体来之前有两个准备能省不少事：一是提前确认人数，按人数订对应大小的包厢，宁可大一点也别挤着；二是把饮料零食的需求提前商量好，能自带就自带，省下的钱比包厢费还多。因为价格低，店里的客流结构以年轻人为主，晚上八点以后会比较吵，走廊里人来人往，喜欢安静的话建议选工作日下午。点歌系统偏老，如果点不到想唱的新歌，可以让服务员帮忙从后台添加，多数门店是支持的。包厢里的麦克风电池偶尔会没电，进房后先试一下，有问题立刻叫服务员换，别等到唱到一半才发现。商场楼层里有洗手间和便利店，需要买东西比较方便。总体来看，讴K拉是一家以低价和大包厢为卖点的量贩式KTV，适合预算有限、人多热闹的学生聚会和团体活动，不适合对音响和环境有要求的场合。想省钱的话，工作日下午是最佳时段；如果想要好一点的体验，建议加一点预算换同商圈的其他店。'),
(14, '星聚会KTV拱墅区万达店开在杭行路666号万达广场C座1到2层，人均消费大约60元，综合评分4.7分，累计685条评价、销量17771，营业时间从上午十点到晚上十点。\n\n作为连锁品牌门店，这家店横跨一到两层，规模不小，包厢数量充足，从几人小包到十几人的聚会包都能安排。连锁店的好处是下限比较有保障：音响设备的维护、包厢的卫生、服务流程都相对标准化，不太会出现特别离谱的体验，4.7分的评分也印证了这一点，而且这个分数是在消费人次接近1.8万的基础上取得的，可信度比评价数很少的店要高。曲库更新跟得上主流，常见的新歌和老歌都能点到，点歌系统操作也比较顺手。\n\n价格是这家店的优势之一，人均60元在这个配置里算相当不错，性价比明显高于同商圈的几家，尤其是对比魅这种人均88元的店。比较划算的做法同样是买团购套餐，通常比现场单点便宜，套餐一般会按包厢类型和时长区分，人数多的时候选大包套餐更合适。酒水小吃属于KTV的常规定价，比外面贵，但不至于离谱。\n\n最需要注意的是营业时间。这家店10:00到22:00营业，是这一批KTV里收档最早的，想唱深夜场或者通宵的话，得换一家（同商圈的讴K拉营业到凌晨两点、运河上街的开乐迪是24小时）。所以如果聚会时间安排在晚上，建议早点开始，20:00以后进场的话实际能唱的时间就不多了，性价比会下降。周末下午和晚上是用场高峰，建议提前订房，避免到了没包厢，尤其是四人以上的大包。\n\n位置在万达广场C座，看电影、吃饭、唱歌可以一次安排完，商场停车位充足，看电影的话凭票还能减免停车费，是周末一站式休闲比较省心的选择。周边餐饮选择也多，唱完可以直接在商场里吃饭。\n\n如果是下午或者傍晚的聚会，这家店其实是同商圈里比较均衡的选择：设备不差、价格不高、位置又方便，唯一要迁就的就是十点收档。安排上可以把唱歌放在前面、吃饭放在后面，比如下午三点进场唱到六点，然后下楼吃饭，这样时间和预算都比较好控制。订房时建议问清楚套餐时长和超时计费方式，连锁店的规则比较统一，一般续时按半小时算。带小孩来唱的话，下午场人少、曲库里的儿歌也够，比晚上更适合。万达广场周边停车方便，看电影和吃饭都在同一栋楼，一站式安排省时间。因为营业到十点，晚上八点半之后前台通常就不再接新单了，想唱晚场要早点到。综合来看，星聚会是一家配置均衡、性价比突出的连锁KTV：设备稳定、价格实惠、位置方便，适合朋友聚会、家庭出行、看电影之后的顺路安排。唯一需要迁就的是它晚上十点就结束营业，不适合夜猫子，也不适合想通宵的局。如果想要又好又便宜、时间又早的场次，它是这一片比较合适的选择。');
